static int cmp_entry(const void *a, const void *b) {
    const Entry *ea = (const Entry *)a;
    const Entry *eb = (const Entry *)b;
    if (ea->r != eb->r) return ea->r - eb->r;
    return ea->c - eb->c;
}

static void add_entry(Entry **arr, int *count, int *cap, int r, int c, double v) {
    if (*count == *cap) {
        *cap = (*cap ? *cap * 2 : 16);
        *arr = realloc(*arr, (size_t)*cap * sizeof(Entry));
        if (!*arr) die("out of memory");
    }
    (*arr)[*count].r = r;
    (*arr)[*count].c = c;
    (*arr)[*count].v = v;
    (*count)++;
}

static CSRMatrix *build_csr(int n, Entry *entries, int count, int symmetric) {
    if (count > 0) qsort(entries, (size_t)count, sizeof(Entry), cmp_entry);

    int *row_ptr = xcalloc((size_t)n + 1, sizeof(int));
    int *tmp_count = xcalloc((size_t)n, sizeof(int));

    int unique = 0;
    for (int i = 0; i < count; ) {
        int r = entries[i].r;
        int c = entries[i].c;
        double sum = 0.0;
        while (i < count && entries[i].r == r && entries[i].c == c) {
            sum += entries[i].v;
            i++;
        }
        entries[unique].r = r;
        entries[unique].c = c;
        entries[unique].v = sum;
        unique++;
        tmp_count[r]++;
    }

    for (int i = 0; i < n; i++) row_ptr[i + 1] = row_ptr[i] + tmp_count[i];
    free(tmp_count);

    int *col_idx = xmalloc((size_t)unique * sizeof(int));
    double *vals = xmalloc((size_t)unique * sizeof(double));
    int *next = xcalloc((size_t)n, sizeof(int));

    for (int i = 0; i < unique; i++) {
        int r = entries[i].r;
        int pos = row_ptr[r] + next[r]++;
        col_idx[pos] = entries[i].c;
        vals[pos] = entries[i].v;
    }
    free(next);

    CSRMatrix *m = xmalloc(sizeof(CSRMatrix));
    m->n = n;
    m->nnz = unique;
    m->row_ptr = row_ptr;
    m->col_idx = col_idx;
    m->vals = vals;
    m->symmetric = symmetric;
    return m;
}

static double *compute_diag(CSRMatrix *m) {
    double *diag = xcalloc((size_t)m->n, sizeof(double));
    for (int i = 0; i < m->n; i++) {
        for (int idx = m->row_ptr[i]; idx < m->row_ptr[i + 1]; idx++) {
            if (m->col_idx[idx] == i) diag[i] += m->vals[idx];
        }
    }
    return diag;
}

static CSRMatrix *read_matrix(const char *filename) {
    FILE *f = fopen(filename, "r");
    if (!f) die("cannot open matrix file");

