static double *read_vector(const char *filename, int *n_out) {
    FILE *f = fopen(filename, "r");
    if (!f) die("cannot open rhs file");
    int n;
    if (fscanf(f, "%d", &n) != 1) {
        fclose(f);
        die("failed to read vector dimension");
    }
    if (n <= 0) die("invalid vector dimension");
    double *x = xmalloc((size_t)n * sizeof(double));
    for (int i = 0; i < n; i++) {
        if (fscanf(f, "%lf", &x[i]) != 1) {
            fclose(f);
            free(x);
            die("failed to read vector entry");
        }
    }
    fclose(f);
    *n_out = n;
    return x;
}

static void write_matrix_market(const char *filename, int n, int nnz, Entry *entries) {
    FILE *f = fopen(filename, "w");
    if (!f) die("cannot open output matrix file");
    fprintf(f, "%%%%MatrixMarket matrix coordinate real symmetric\n");
    fprintf(f, "%d %d %d\n", n, n, nnz);
    for (int k = 0; k < nnz; k++) {
        fprintf(f, "%d %d %.15g\n", entries[k].r + 1, entries[k].c + 1, entries[k].v);
    }
    fclose(f);
}

static int cmp_entry_rc(const void *a, const void *b) {
    const Entry *ea = (const Entry *)a;
    const Entry *eb = (const Entry *)b;
    if (ea->r != eb->r) return ea->r - eb->r;
    return ea->c - eb->c;
}

static void generate_laplacian2d(int n, const char *output) {
    int N = n * n;
    int cap = N * 3;
    Entry *entries = xmalloc((size_t)cap * sizeof(Entry));
    int count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int row = i * n + j;
            entries[count].r = row;
            entries[count].c = row;
            entries[count].v = 4.0;
            count++;
            if (j > 0) {
                int col = i * n + (j - 1);
                entries[count].r = row;
                entries[count].c = col;
                entries[count].v = -1.0;
                count++;
            }
            if (i > 0) {
                int col = (i - 1) * n + j;
                entries[count].r = row;
                entries[count].c = col;
                entries[count].v = -1.0;
                count++;
            }
        }
    }
    qsort(entries, (size_t)count, sizeof(Entry), cmp_entry_rc);
    write_matrix_market(output, N, count, entries);
    free(entries);
}

static void generate_laplacian3d(int n, const char *output) {
    int N = n * n * n;
    int cap = N * 4;
    Entry *entries = xmalloc((size_t)cap * sizeof(Entry));
    int count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < n; k++) {
                int row = (i * n + j) * n + k;
                entries[count].r = row;
                entries[count].c = row;
                entries[count].v = 6.0;
                count++;
                if (k > 0) {
                    int col = row - 1;
                    entries[count].r = row;
                    entries[count].c = col;
                    entries[count].v = -1.0;
                    count++;
                }
                if (j > 0) {
                    int col = row - n;
                    entries[count].r = row;
                    entries[count].c = col;
                    entries[count].v = -1.0;
                    count++;
                }
                if (i > 0) {
                    int col = row - n * n;
                    entries[count].r = row;
                    entries[count].c = col;
                    entries[count].v = -1.0;
                    count++;
                }
            }
        }
    }
    qsort(entries, (size_t)count, sizeof(Entry), cmp_entry_rc);
    write_matrix_market(output, N, count, entries);
