    int *order = xmalloc((size_t)n * sizeof(int));
    int order_count = 0;
    int *queue = xmalloc((size_t)n * sizeof(int));
    int qhead = 0, qtail = 0;

    while (order_count < n) {
        int start = -1;
        for (int i = 0; i < n; i++) {
